import math
def cubic(p0,p1,p2,p3,t):
    return tuple((1-t)**3*a+3*(1-t)**2*t*b+3*(1-t)*t*t*c+t**3*d for a,b,c,d in zip(p0,p1,p2,p3))
pts=[]
segs=[((60,62),(36,48),(36,16),(66,2)),((66,2),(84,14),(82,50),(60,62))]
for r in (0,120,240):
    a=math.radians(r); ca,sa=math.cos(a),math.sin(a)
    for s in segs:
        for i in range(101):
            x,y=cubic(*s,i/100); dx,dy=x-60,y-60
            pts.append((60+dx*ca-dy*sa,60+dx*sa+dy*ca))
xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
